import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const src = path.join(root, 'studio-src');
const icons = JSON.parse(fs.readFileSync(path.join(src, 'icons-data.json'), 'utf8'));

const template = fs.readFileSync(path.join(src, 'index.html'), 'utf8');
const css = [
  '/* Generated by build.mjs — do not edit the built file. */',
  fs.readFileSync(path.join(src, 'styles-base.css'), 'utf8'),
  fs.readFileSync(path.join(src, 'styles-controls.css'), 'utf8')
].join('\n\n');
const data = fs.readFileSync(path.join(src, 'data.js'), 'utf8');
const app = fs.readFileSync(path.join(src, 'app.js'), 'utf8');

const js = [
  '"use strict";',
  '/* Icon data: Lucide (ISC), Tabler (MIT), Phosphor (MIT), Heroicons (MIT). */',
  `const ICON_DATA = ${JSON.stringify(icons)};`,
  data,
  app
].join('\n\n');

if (js.includes('</script')) throw new Error('JS contains a closing script tag');
if (css.includes('</style')) throw new Error('CSS contains a closing style tag');

const html = template
  .replace('/*__CSS__*/', () => css)
  .replace('/*__JS__*/', () => js);

const out = path.join(root, 'mishkat-theme-studio.html');
fs.writeFileSync(out, html, 'utf8');
console.log(`built ${out}`);
console.log(`html ${(html.length / 1024).toFixed(1)} KiB · css ${(css.length / 1024).toFixed(1)} KiB · js ${(js.length / 1024).toFixed(1)} KiB · icons ${Object.keys(icons).length}`);
